#!/usr/bin/env bash
# Generates the chart's CRD and ClusterRole templates from controller-gen
# output, so the chart can never drift from the API types and RBAC markers.
# Run by `make manifests` (after controller-gen); do not edit the outputs.
#
#   config/crd/bases/smbhealer.herschel.io_<plural>.yaml
#     -> production/smb-mount-healer/templates/crds/<plural>.yaml
#   config/rbac/role-<component>.yaml
#     -> production/smb-mount-healer/templates/rbac/clusterrole-<component>.yaml
#   monitoring/dashboards/smb-mount-healer.json, monitoring/alerts/smb-mount-healer.rules.yaml
#     -> production/smb-mount-healer/files/ (read with .Files.Get, never templated)
set -euo pipefail

cd "$(dirname "$0")/.."

CHART=production/smb-mount-healer
CRD_SRC=config/crd/bases
RBAC_SRC=config/rbac
CRD_OUT="$CHART/templates/crds"
RBAC_OUT="$CHART/templates/rbac"

command -v yq >/dev/null || { echo "sync-chart: yq is required" >&2; exit 1; }

# Placeholders survive yq untouched and are then turned into template lines.
LABELS_PH='__SMBMH_LABELS__'
KEEP_PH='__SMBMH_KEEP__'

# gotpl would interpret "{{" in a source file. Nothing generated contains it
# today; if that ever changes, escape it here instead of shipping a broken chart.
guard() {
  if grep -q '{{' "$1"; then
    echo "sync-chart: $1 contains '{{', which would break the Helm template; escape it in hack/sync-chart.sh" >&2
    exit 1
  fi
}

mkdir -p "$CRD_OUT" "$RBAC_OUT"
rm -f "$CRD_OUT"/*.yaml "$RBAC_OUT"/clusterrole-*.yaml

shopt -s nullglob
crds=("$CRD_SRC"/smbhealer.herschel.io_*.yaml)
[ "${#crds[@]}" -gt 0 ] || { echo "sync-chart: no CRDs in $CRD_SRC (run controller-gen first)" >&2; exit 1; }

for src in "${crds[@]}"; do
  guard "$src"
  plural=$(basename "$src" .yaml)
  plural=${plural#smbhealer.herschel.io_}
  out="$CRD_OUT/$plural.yaml"
  {
    echo "# GENERATED by hack/sync-chart.sh from $src - do not edit."
    echo '{{- if .Values.crds.install }}'
    yq "del(.metadata.labels)
        | .metadata.labels = \"$LABELS_PH\"
        | .metadata.annotations.\"$KEEP_PH\" = \"x\"
        | ... comments = \"\"" "$src" \
      | sed -e '/^---$/d' \
            -e "s/^  labels: $LABELS_PH\$/  labels:\n    {{- include \"smb-mount-healer.labels\" . | nindent 4 }}/" \
            -e "s/^    $KEEP_PH: x\$/    {{- if .Values.crds.keep }}\n    helm.sh\/resource-policy: keep\n    {{- end }}/"
    echo '{{- end }}'
  } >"$out"
  if grep -q '__SMBMH_' "$out"; then
    echo "sync-chart: placeholder left in $out (unexpected yq output layout)" >&2
    exit 1
  fi
done

for component in controlplane worker; do
  src="$RBAC_SRC/role-$component.yaml"
  [ -f "$src" ] || { echo "sync-chart: $src is missing (run controller-gen first)" >&2; exit 1; }
  guard "$src"
  out="$RBAC_OUT/clusterrole-$component.yaml"
  {
    echo "# GENERATED by hack/sync-chart.sh from $src - do not edit."
    echo "# The rules come from the +kubebuilder:rbac markers in internal/$component."
    echo "{{- \$ctx := dict \"context\" . \"component\" \"$component\" }}"
    echo 'apiVersion: rbac.authorization.k8s.io/v1'
    echo 'kind: ClusterRole'
    echo 'metadata:'
    echo '  name: {{ include "smb-mount-healer.componentName" $ctx }}'
    echo '  labels:'
    echo '    {{- include "smb-mount-healer.componentLabels" $ctx | nindent 4 }}'
    yq '{"rules": .rules}' "$src"
  } >"$out"
done

# Monitoring sources: a chart can only read files inside its own directory.
# Copied verbatim; the templates load them with .Files.Get (no tpl), so the
# Grafana/Prometheus "{{ }}" in them stay literal.
FILES_OUT="$CHART/files"
mkdir -p "$FILES_OUT"
rm -f "$FILES_OUT"/*
cp monitoring/dashboards/smb-mount-healer.json "$FILES_OUT/smb-mount-healer.json"
cp monitoring/alerts/smb-mount-healer.rules.yaml "$FILES_OUT/smb-mount-healer.rules.yaml"

echo "sync-chart: wrote ${#crds[@]} CRDs and 2 ClusterRoles into $CHART/templates, monitoring sources into $FILES_OUT"
